#pragma once
// Explicit local beat-grid preparation. Never loads a sample into an engine or replaces manual edits.
class TrackPreanalysis final:public juce::Thread {
 juce::CriticalSection mutex;juce::WaitableEvent wake;juce::Array<juce::File> queue;std::set<juce::String> queued;std::map<juce::String,std::pair<double,double>> ranges;juce::String status;std::atomic<uint64_t> revision{0};int total=0,completed=0;bool active=false;
 void report(juce::String text){const juce::ScopedLock g(mutex);status=std::move(text);++revision;}
public:
 static TrackPreanalysis& instance(){static TrackPreanalysis worker;return worker;}
 TrackPreanalysis():Thread("Prepare track beat grids"){}~TrackPreanalysis()override{signalThreadShouldExit();wake.signal();stopThread(-1);}
 void request(const juce::Array<juce::File>& files,double low=80,double high=160){const juce::ScopedLock g(mutex);if(!active&&queue.isEmpty()){total=completed=0;}for(auto f:files)if(f.existsAsFile()&&!f.hasFileExtension("sfz")&&queued.insert(f.getFullPathName()).second){queue.add(f);++total;ranges[f.getFullPathName()]={low,high};}if(!active){status="Track analysis queued: "+juce::String(queue.size())+" tracks";++revision;}if(!isThreadRunning())startThread(juce::Thread::Priority::background);wake.signal();}
 bool busy(){const juce::ScopedLock g(mutex);return active||!queue.isEmpty();}
 uint64_t version()const{return revision.load();}juce::String statusText(){const juce::ScopedLock g(mutex);return status;}
 void run()override{while(!threadShouldExit()){juce::File file;double low=80,high=160;{const juce::ScopedLock g(mutex);if(!queue.isEmpty()){file=queue[0];auto range=ranges[file.getFullPathName()];low=range.first;high=range.second;ranges.erase(file.getFullPathName());queue.remove(0);active=true;}}if(file==juce::File()){wake.wait(100);continue;}bool ok=false;int lastPercent=-1;auto progress=[&](float value){int percent=juce::jlimit(0,100,(int)(value*100));if(percent==lastPercent)return;lastPercent=percent;const juce::ScopedLock g(mutex);status="Analysing "+file.getFileName()+": "+juce::String(percent)+"% | "+juce::String(completed)+"/"+juce::String(total)+" complete";++revision;};progress(0);double sliceStart=juce::Time::getMillisecondCounterHiRes();auto cancel=[&]{if(threadShouldExit())return true;double worked=juce::Time::getMillisecondCounterHiRes()-sliceStart;if(worked>=3){wake.wait(juce::jlimit(1,80,(int)std::ceil(worked*4)));sliceStart=juce::Time::getMillisecondCounterHiRes();}return threadShouldExit();};try{juce::AudioFormatManager formats;formats.registerBasicFormats();std::unique_ptr<juce::AudioFormatReader> reader(formats.createReaderFor(file));if(reader&&reader->lengthInSamples>0&&reader->lengthInSamples<INT_MAX){AudioData audio;audio.path=file.getFullPathName();audio.contentHash=LibraryStore::fingerprint(file);audio.rate=reader->sampleRate;auto cache=LibraryStore::root().getChildFile("track-analysis-v3").getChildFile(audio.contentHash+".xml");audio.buffer.setSize(juce::jmin(2,(int)reader->numChannels),(int)reader->lengthInSamples);TrackGrid grid;ok=TrackAnalyser::loadCache(cache,audio,low,high,grid);if(!ok){bool read=true;for(int start=0;start<audio.buffer.getNumSamples()&&!cancel();start+=16384){read&=reader->read(&audio.buffer,start,juce::jmin(16384,audio.buffer.getNumSamples()-start),start,true,true);progress(.15f*(start+juce::jmin(16384,audio.buffer.getNumSamples()-start))/audio.buffer.getNumSamples());juce::Thread::yield();}if(read&&!cancel()){grid=TrackAnalyser::analyse(audio,low,high,cancel,[&](float value){progress(.15f+.85f*value);});if(!cancel()&&grid.anchors.size()>1){TrackAnalyser::saveCache(cache,low,high,grid);ok=cache.existsAsFile();}}}if(ok)TrackAnalyser::markPrepared(file,audio.contentHash);}}catch(...){} {const juce::ScopedLock g(mutex);queued.erase(file.getFullPathName());++completed;active=false;status=(ok?"Track analysis ready: ":"Track analysis failed: ")+file.getFileName()+" | "+juce::String(completed)+"/"+juce::String(total)+" complete";++revision;}}}
};
